import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import{pairVector,fibreAudit,starFibres,puzzleAssignments,directionOptions,awardStage,ringWitnessAudit,installStations}from '../kakeya-math.js';import{World}from '../world.js';import{findPath}from '../navigation.js';
test('every chamber starts unsolved and exact star completion covers each direction',()=>{for(const n of [2,3,4]){const N=2**n;assert.equal(fibreAudit(starFibres(n,puzzleAssignments(n)),n).covered,0);const audit=fibreAudit(starFibres(n),n);assert.equal(audit.weight,3*N-2);assert.equal(audit.covered,N-1);assert.deepEqual(audit.sums,Array(N-1).fill(N/2));for(let a=1;a<N;a++)assert.ok(directionOptions(a,n).includes(a));}});
test('removing a directional pair creates the corresponding coverage deficit',()=>{const f=starFibres(4);f[7]=[0];const audit=fibreAudit(f,4);assert.equal(audit.covered,14);assert.equal(audit.sums[6],0);assert.equal(audit.energy,974);assert.equal(fibreAudit(starFibres(4),4).energy,975);assert.throws(()=>pairVector([0,0],4));});
test('supplied 46-point ring witness contains all 120 primitive projective lines',()=>{const witness=JSON.parse(fs.readFileSync(new URL('../kakeya/z4-witness.json',import.meta.url)));const a=ringWitnessAudit(witness.set,4);assert.equal(a.points,46);assert.equal(a.directions,120);assert.equal(a.covered,120);for(const row of a.lines)assert.equal(row.line.length,4);});
test('rewards survive JSON save and cannot be collected twice',()=>{let s={gold:0};assert.equal(awardStage(s,2),10);s=JSON.parse(JSON.stringify(s));assert.equal(awardStage(s,2),0);awardStage(s,3);awardStage(s,4);assert.equal(s.gold,70);});
test('stations exist on reachable floors and preserve story state',()=>{const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));const w=new World(data);const before=w.save();installStations(w);const stations=w.data.scenes.filter(s=>s.objects.some(o=>o.kakeyaStation));assert.ok(stations.length>1);for(const s of stations){const o=s.objects.find(o=>o.kakeyaStation);assert.equal(s.floor[o.xy[1]][o.xy[0]],'.',s.key);assert.ok(findPath(s,s.arrive,o.xy,1).length,s.key);}assert.equal(w.save(),before);installStations(w);for(const s of stations)assert.equal(s.objects.filter(o=>o.kakeyaStation).length,1);});
